function getPolishSentencesPlural(count: number): string {
  if (count === 1) return 'zdanie';
  const lastTwo = count % 100;
  const last = count % 10;
  if (lastTwo >= 12 && lastTwo <= 14) return 'zdań';
  if (last >= 2 && last <= 4) return 'zdania';
  return 'zdań';
}


